<?php
require_once __DIR__ . '/koneksi.php';
require_once __DIR__ . '/Pasien.php';
if(isset($_GET['hapus'])){$q=$pdo->prepare('DELETE FROM pasien WHERE id=?');$q->execute([(int)$_GET['hapus']]);header('Location: index.php');exit;}
if(isset($_POST['simpan'])){$o=new Pasien($_POST['nama'],$_POST['umur'],$_POST['jk'],$_POST['keluhan'],$_POST['tanggal']);$id=(int)($_POST['id']??0);if($id){$q=$pdo->prepare('UPDATE pasien SET nama=?,umur=?,jenis_kelamin=?,keluhan=?,tanggal_masuk=? WHERE id=?');$q->execute([$o->nama,$o->umur,$o->jk,$o->keluhan,$o->tanggal,$id]);}else{$q=$pdo->prepare('INSERT INTO pasien(nama,umur,jenis_kelamin,keluhan,tanggal_masuk) VALUES(?,?,?,?,?)');$q->execute([$o->nama,$o->umur,$o->jk,$o->keluhan,$o->tanggal]);}header('Location: index.php');exit;}
$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare('SELECT * FROM pasien WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}$rows=$pdo->query('SELECT * FROM pasien ORDER BY id DESC')->fetchAll();
?>
