<form method="post" class=""><input type="hidden" name="id" value="<?= htmlspecialchars($edit['id']??'') ?>"><div class="grid"><div><label>Nama pasien</label><input name="nama" required value="<?= htmlspecialchars($edit['nama']??'') ?>"></div><div><label>Umur</label><input type="number" min="1" name="umur" required value="<?= htmlspecialchars($edit['umur']??'') ?>"></div><div><label>Jenis kelamin</label><select name="jk"><option>Laki-laki</option><option>Perempuan</option></select></div><div><label>Tanggal masuk</label><input type="date" name="tanggal" required value="<?= htmlspecialchars($edit['tanggal_masuk']??date('Y-m-d')) ?>"></div><div><label>Keluhan</label><input name="keluhan" required value="<?= htmlspecialchars($edit['keluhan']??'') ?>"></div></div><p><button name="simpan">Simpan Data Pasien</button></p></form>
<h2>Data Pasien</h2><table class="table"><tr><th>ID</th><th>Nama</th><th>Umur</th><th>Jenis kelamin</th><th>Keluhan</th><th>Tanggal masuk</th><th>Aksi</th></tr><?php foreach($rows as $r):?><tr><td><?=$r['id']?></td><td><?=htmlspecialchars($r['nama'])?></td><td><?=$r['umur']?></td><td><?=$r['jenis_kelamin']?></td><td><?=htmlspecialchars($r['keluhan'])?></td><td><?=$r['tanggal_masuk']?></td><td><a href="?edit=<?=$r['id']?>">Edit</a> | <a href="?hapus=<?=$r['id']?>" onclick="return confirm('Hapus data?')">Hapus</a></td></tr><?php endforeach;?></table>
